(() => {
  'use strict';
  const $ = s => document.querySelector(s);
  const KEY = 'focusflow.tasks.v1';
  const dateKey = (d = new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  let today = dateKey();
  const offset = n => { const d = new Date(); d.setDate(d.getDate()+n); return dateKey(d); };
  const parseDate = s => new Date(`${s}T12:00:00`);
  const colors = ['#777777','#777777','#777777','#777777','#777777','#777777'];
  const initial = [
    ['Finish calculus problem set','Mathematics',-1,'High',false],
    ['Read chapter 5: Cell division','Biology',0,'High',false],
    ['Draft the literature essay','English Literature',0,'Medium',false],
    ['Practice Newton’s laws problems','Physics',0,'Medium',false],
    ['Review lecture notes','Mathematics',0,'Low',true],
    ['Submit lab observation notes','Biology',0,'Medium',true],
    ['Prepare presentation slides','Computer Science',1,'High',false],
    ['Complete the research outline','English Literature',2,'Medium',false],
    ['Work on the algorithm assignment','Computer Science',4,'Low',false]
  ].map(([title,subject,days,priority,completed])=>({id:crypto.randomUUID(),title,subject,deadline:offset(days),priority,completed}));
  let tasks;
  const validTask = t => t && typeof t.id==='string' && typeof t.title==='string' && typeof t.subject==='string' && /^\d{4}-\d{2}-\d{2}$/.test(t.deadline) && !isNaN(parseDate(t.deadline)) && ['High','Medium','Low'].includes(t.priority) && (t.notes===undefined||typeof t.notes==='string') && typeof t.completed==='boolean';
  try {const saved=JSON.parse(localStorage.getItem(KEY));tasks=Array.isArray(saved)?saved.filter(validTask):initial;} catch {tasks=initial;}
  let view='today', subject='', priority='', query='';
  let layout='bulletin';
  try{const stored=localStorage.getItem('focusflow.layout');if(['bulletin','dashboard'].includes(stored))layout=stored;}catch{}
  let lastAction=null;
  let storageFailed = false;
  const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const subjects = () => [...new Set(tasks.map(t=>t.subject))].sort();
  const color = s => colors[subjects().indexOf(s)%colors.length] || colors[0];
  let toastTimer;
  function toast(message,undo=false){$('#toast').textContent=message;if(undo)$('#toast').innerHTML=escape(message)+' <button type="button" id="undo-action" data-undo="true">Undo</button>';$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),undo?8000:2600);}
  function undoLast(){if(!lastAction)return;const action=lastAction;lastAction=null;if(action.type==='delete'){if(!tasks.some(t=>t.id===action.task.id))tasks.push(action.task);}else{const task=tasks.find(t=>t.id===action.id);if(task)task.completed=action.before;window.FocusFlowPaper?.cancel(action.id);}save();if(!storageFailed)toast('Last change undone.');}
  function setLayout(next){layout=next;if(view==='board')view='all';try{localStorage.setItem('focusflow.layout',next);}catch{toast('Layout changed for this session.');}render();}
  $('#bulletin-layout').onclick=()=>setLayout('bulletin');$('#dashboard-layout').onclick=()=>setLayout('dashboard');
  function save(){try{localStorage.setItem(KEY,JSON.stringify(tasks));storageFailed=false;}catch{storageFailed=true;toast('Device storage is unavailable. Changes last for this session.');}$('.local-badge').innerHTML=storageFailed?'Session only · storage unavailable':'<i></i> Saved on this device';render();}
  function theme(){const dark=document.documentElement.dataset.theme==='dark';$('#theme-label').textContent=dark?'Switch to light mode':'Switch to dark mode';$('#header-theme-label').textContent=dark?'Dark':'Light';$('#mobile-theme').setAttribute('aria-checked',String(dark));document.documentElement.style.colorScheme=dark?'dark':'light';}
  try{document.documentElement.dataset.theme=localStorage.getItem('focusflow.theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');}catch{}
  function toggleTheme(){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('focusflow.theme',document.documentElement.dataset.theme);}catch{toast('Theme changed for this session.');}theme();}
  theme();$('#theme').onclick=toggleTheme;$('#mobile-theme').onclick=toggleTheme;
  function setView(next){view=next;render();}
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
  $('#list-view').onclick=()=>setView(view==='board'?'all':view);$('#board-view').onclick=()=>setView('board');
  $('#search').oninput=e=>{query=e.target.value.toLowerCase();renderTasks();};
  $('#subject-filter').onchange=e=>{subject=e.target.value;render();};$('#priority-filter').onchange=e=>{priority=e.target.value;renderTasks();};
  function card(t){const late=t.deadline<today&&!t.completed;return `<article class="task ${layout==='bulletin'&&view!=='board'?'sticky-note':''} ${t.completed?'done':''}" draggable="${view==='board'}" data-id="${escape(t.id)}"><span class="note-pin" aria-hidden="true"><svg viewBox="0 0 32 42" fill="none"><path d="M17 22 13 40" stroke="currentColor" stroke-width="1.5"/><path d="m9 13 14 3-1 10-15-3Z" fill="var(--muted)" stroke="currentColor" stroke-width="1.2"/><ellipse cx="17" cy="12" rx="10" ry="8" transform="rotate(12 17 12)" fill="var(--text)" stroke="var(--inverse)" stroke-width=".7"/><path d="M12 9c1-2 4-2 6-1" stroke="var(--inverse)" stroke-width="1.3" stroke-linecap="round"/></svg></span><button class="check" data-toggle="${escape(t.id)}" aria-label="${t.completed?'Mark incomplete':'Complete'}: ${escape(t.title)}" aria-pressed="${t.completed}">${t.completed?'✓':''}</button><div class="task-info"><button class="task-title" data-edit="${escape(t.id)}">${escape(t.title)}</button>${t.notes?`<p class="note-excerpt">${escape(t.notes)}</p>`:''}<div class="task-meta"><span class="subject-tag" style="--subject-color:${color(t.subject)}">${escape(t.subject)}</span><span>·</span><span class="${late?'late':''}">◷ ${t.deadline===today?'Today':t.deadline===offset(1)?'Tomorrow':parseDate(t.deadline).toLocaleDateString(undefined,{month:'short',day:'numeric'})}${late?' · Overdue':''}</span></div></div><span class="priority ${t.priority}">${t.priority}</span><button class="edit-task" data-edit="${escape(t.id)}" aria-label="Edit ${escape(t.title)}">⋯</button></article>`;}
  function filtered(){return tasks.filter(t=>(!subject||t.subject===subject)&&(!priority||t.priority===priority)&&(!query||`${t.title} ${t.subject}`.toLowerCase().includes(query))&&(view==='today'?t.deadline<=today&&(t.deadline===today||!t.completed):view==='completed'?t.completed:!t.completed)).sort((a,b)=>a.deadline.localeCompare(b.deadline)||['High','Medium','Low'].indexOf(a.priority)-['High','Medium','Low'].indexOf(b.priority));}
  function renderTasks(){const list=filtered();$('#list-count').textContent=list.length;let html='';if(view==='board'){html='<div class="board">'+['High','Medium','Low'].map(p=>`<section class="board-column" data-priority="${p}" aria-label="${p} priority"><h3>${p} priority <span class="muted">${list.filter(t=>t.priority===p).length}</span></h3>${list.filter(t=>t.priority===p).map(card).join('')||'<div class="empty">Drop an assignment here</div>'}</section>`).join('')+'</div>';}else{const groups=view==='today'?[['Overdue',list.filter(t=>t.deadline<today),'overdue'],['Today',list.filter(t=>!t.completed&&t.deadline===today),''],['Completed today',list.filter(t=>t.completed),'']]:[['',list,'']];html=groups.filter(([,items])=>items.length).map(([label,items,cls])=>`${label?`<div class="group-title ${cls}">${cls?'◷':'◦'} ${label} <span>${items.length}</span><span class="line"></span></div>`:''}${layout==='bulletin'?'<div class="note-grid">':''}${items.map(card).join('')}${layout==='bulletin'?'</div>':''}`).join('');}
    $('#tasks').innerHTML=html||`<div class="empty"><strong>${query||subject||priority?'No matching assignments':'A little breathing room.'}</strong>${query||subject||priority?'Try another search or change your filters.':'You’re all caught up here. Add an assignment to plan your next step.'}</div>`;
  }
  function render(){window.FocusFlowProgress?.update({completed:tasks.filter(t=>t.completed).length,total:tasks.length});document.documentElement.dataset.layout=layout;$('#bulletin-layout').setAttribute('aria-pressed',String(layout==='bulletin'));$('#dashboard-layout').setAttribute('aria-pressed',String(layout==='dashboard'));$('#layout-caption').textContent=layout==='bulletin'?'Pin your next steps. Clear a little space.':'Your regular dashboard. Everything in one list.';today=dateKey();const due=tasks.filter(t=>t.deadline===today),done=due.filter(t=>t.completed).length;$('#stat-today').textContent=due.filter(t=>!t.completed).length;$('#stat-overdue').textContent=tasks.filter(t=>t.deadline<today&&!t.completed).length;$('#stat-upcoming').textContent=tasks.filter(t=>t.deadline>today&&!t.completed).length;$('#progress-text').textContent=`${done} of ${due.length}`;const percent=due.length?Math.round(done/due.length*100):0;$('#ring-percent').textContent=percent+'%';$('#ring-stroke').setAttribute('stroke-dashoffset',100-percent);$('#ring').setAttribute('aria-label',`${done} of ${due.length} assignments due today completed`);$('#completed-count').textContent=tasks.filter(t=>t.completed).length;
    const names={today:'My day',all:'All assignments',board:'Priority board',completed:'Completed'};$('#crumb').textContent=names[view];$('#page-title').innerHTML=({today:'My day<span>.</span>',all:'A clear view of what’s next<span>.</span>',board:'Priority board<span>.</span>',completed:'Completed<span>.</span>'})[view];$('#page-subtitle').textContent=({today:'A fresh day, a clear plan. Let’s make a little progress.',all:'Every assignment, one place. Turn a busy week into a plan.',board:'Drag assignments between columns, or edit a card to change its priority.',completed:'Small wins add up. Here’s the progress you’ve made.'})[view];$('#list-title').childNodes[0].textContent=({today:'Today’s assignments ',all:'Your assignments ',board:'Your priority board ',completed:'Your finished assignments '})[view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#list-view').classList.toggle('selected',view!=='board');$('#board-view').classList.toggle('selected',view==='board');
    const opts=subjects();$('#subject-filter').innerHTML='<option value="">All subjects</option>'+opts.map(s=>`<option ${s===subject?'selected':''}>${escape(s)}</option>`).join('');$('#subjects').innerHTML=opts.map(s=>`<option value="${escape(s)}">`).join('');$('#subject-nav').innerHTML=opts.map(s=>`<button class="subject-button" data-subject="${escape(s)}" ${subject===s?'style="background:var(--soft);border-radius:6px"':''}><i class="dot" style="--subject-color:${color(s)}"></i>${escape(s)}<span>${tasks.filter(t=>t.subject===s&&!t.completed).length}</span></button>`).join('');
    $('#date-label').textContent=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase();renderCalendar();const next=tasks.filter(t=>t.deadline>today&&t.deadline<=offset(7)&&!t.completed).sort((a,b)=>a.deadline.localeCompare(b.deadline));$('#upcoming').innerHTML=next.slice(0,3).map(t=>`<div class="upcoming-item"><div class="date-box"><span>${parseDate(t.deadline).toLocaleDateString('en',{month:'short'})}</span><strong>${parseDate(t.deadline).getDate()}</strong></div><div><h3>${escape(t.title)}</h3><p><span style="color:${color(t.subject)}">●</span> ${escape(t.subject)}</p></div></div>`).join('')||'<p class="empty">No deadlines in the next 7 days.</p>';renderTasks();
  }
  function renderCalendar(){const d=new Date(),y=d.getFullYear(),m=d.getMonth(),first=(new Date(y,m,1).getDay()+6)%7,total=new Date(y,m+1,0).getDate();$('#calendar-title').textContent=d.toLocaleDateString('en',{month:'long',year:'numeric'});$('#calendar').innerHTML=['M','T','W','T','F','S','S'].map(x=>`<span class="day-name">${x}</span>`).join('')+'<span></span>'.repeat(first)+Array.from({length:total},(_,i)=>{const key=dateKey(new Date(y,m,i+1));return `<span class="${key===today?'calendar-today ':''}${tasks.some(t=>t.deadline===key&&!t.completed)?'has-task':''}" title="${key}">${i+1}</span>`;}).join('');}
  function openTask(id){const t=tasks.find(t=>t.id===id);$('#task-form').reset();$('#task-id').value=t?.id||'';$('#modal-title').textContent=t?'Edit assignment':'New assignment';$('#delete-task').hidden=!t;$('#task-title').value=t?.title||'';$('#task-notes').value=t?.notes||'';$('#task-subject').value=t?.subject||subject;$('#task-deadline').value=t?.deadline||today;$('#task-priority').value=t?.priority||'Medium';$('#task-dialog').showModal();$('#task-title').focus();}
  $('#add-task').onclick=()=>openTask();$('#add-inline').onclick=()=>openTask();$('#close-dialog').onclick=()=>$('#task-dialog').close();$('#shortcuts').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();
  $('#task-form').onsubmit=e=>{e.preventDefault();const title=$('#task-title').value.trim(),sub=$('#task-subject').value.trim();if(!title||!sub){toast('Please enter a title and subject.');return;}const id=$('#task-id').value,existing=tasks.find(t=>t.id===id);const t={id:id||crypto.randomUUID(),title,notes:$('#task-notes').value.trim(),subject:sub,deadline:$('#task-deadline').value,priority:$('#task-priority').value,completed:existing?.completed||false};if(existing)tasks=tasks.map(x=>x.id===id?t:x);else tasks.push(t);if(!existing){if(view==='completed'||(view==='today'&&t.deadline>today))view='all';if(subject&&subject!==t.subject)subject='';if(priority&&priority!==t.priority){priority='';$('#priority-filter').value='';}if(query&&!`${t.title} ${t.subject}`.toLowerCase().includes(query)){query='';$('#search').value='';}}$('#task-dialog').close();save();if(!existing){try{window.FocusFlowPin?.play(t.id);}catch{}}if(!storageFailed)toast(existing?'Assignment updated.':'A new step, added to your plan.');};
  $('#delete-task').onclick=()=>{const id=$('#task-id').value;const task=tasks.find(t=>t.id===id);if(!task)return;lastAction={type:'delete',task};tasks=tasks.filter(t=>t.id!==id);window.FocusFlowPaper?.cancel(id);$('#task-dialog').close();save();if(!storageFailed)toast('Assignment deleted.',true);};
  document.addEventListener('click',e=>{if(e.target.closest('[data-undo]')){undoLast();return;}const toggle=e.target.closest('[data-toggle]'),edit=e.target.closest('[data-edit]'),sub=e.target.closest('[data-subject]');if(toggle){const t=tasks.find(t=>t.id===toggle.dataset.toggle);if(!t)return;const before=t.completed;const rect=toggle.closest('.task')?.getBoundingClientRect();lastAction={type:'complete',id:t.id,before};t.completed=!before;save();if(t.completed&&rect){try{window.FocusFlowPaper?.complete({task:{...t},rect:{left:rect.left,top:rect.top,width:rect.width,height:rect.height}});}catch{}}else window.FocusFlowPaper?.cancel(t.id);if(!storageFailed)toast(t.completed?'Assignment complete. A little more room to think.':'Assignment marked incomplete.',true);}else if(edit)openTask(edit.dataset.edit);else if(sub){subject=subject===sub.dataset.subject?'':sub.dataset.subject;view='all';render();}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')return;if(e.target.matches('input,textarea,select')||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&lastAction){e.preventDefault();undoLast();return;}if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='n'){e.preventDefault();openTask();}else if(e.key==='/'){e.preventDefault();$('#search').focus();}else if(['1','2','3'].includes(e.key))setView(['today','all','board'][Number(e.key)-1]);else if(e.key==='?')$('#help-dialog').showModal();});
  document.addEventListener('dragstart',e=>{const card=e.target.closest('.task');if(card&&view==='board'){e.dataTransfer.setData('text/plain',card.dataset.id);e.dataTransfer.effectAllowed='move';}});
  document.addEventListener('dragover',e=>{const col=e.target.closest('.board-column');if(col){e.preventDefault();col.classList.add('drag-over');}});
  document.addEventListener('dragleave',e=>{const col=e.target.closest('.board-column');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drag-over');});
  document.addEventListener('dragend',()=>document.querySelectorAll('.drag-over').forEach(c=>c.classList.remove('drag-over')));
  document.addEventListener('drop',e=>{const col=e.target.closest('.board-column');if(!col)return;e.preventDefault();const t=tasks.find(t=>t.id===e.dataTransfer.getData('text/plain'));if(t){t.priority=col.dataset.priority;save();if(!storageFailed)toast(`Moved to ${t.priority.toLowerCase()} priority.`);}});
  window.addEventListener('storage',e=>{if(e.key===KEY){try{const saved=JSON.parse(e.newValue);if(Array.isArray(saved)){tasks=saved.filter(validTask);render();}}catch{}}if(e.key==='focusflow.layout'&&['bulletin','dashboard'].includes(e.newValue)){layout=e.newValue;render();}if(e.key==='focusflow.theme'&&e.newValue){document.documentElement.dataset.theme=e.newValue;theme();}});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});setInterval(()=>{if(dateKey()!==today)render();},60000);
  save();
})();
